CORE = [s for s in STYLES if not s.get("signature")]
SIGNATURE = [s for s in STYLES if s.get("signature")]
AXES = ["color", "rustic", "decor", "warmth", "era", "mood", "green"]

if __name__ == "__main__":
    import json, re, pathlib
    for s in STYLES:
        assert len(s["palette"]) == 9 and len(s["words"]) == 3 and len(s["pieces"]) == 5, s["id"]
        assert all(re.fullmatch(r"#[0-9A-F]{6}", c["hex"]) for c in s["palette"]), s["id"]
        assert set(s["profile"]) == set(AXES), s["id"]
    out = pathlib.Path(__file__).with_name("styles.json")
    out.write_text(json.dumps(dict(axes=AXES, styles=STYLES), indent=1, ensure_ascii=False))
    print("ok", len(CORE), "core +", len(SIGNATURE), "signature ->", out)
